import requests

def test_post_api_auth_sign_out_with_valid_bearer_token():
    base_url = "http://localhost:8000"
    endpoint = "/api/auth/sign-out"
    url = base_url + endpoint
    token = "eyJhbGciOiJFUzI1NiIsImtpZCI6ImI4MTI2OWYxLTIxZDgtNGYyZS1iNzE5LWMyMjQwYTg0MGQ5MCIsInR5cCI6IkpXVCJ9..7tnorXc_v1GajgbKOx_eL1YOszeBUfjHR8eD_sTpsMVGd1byScCiaea2NrexKmTDL3dIlmobE5Mqry_s39Blkw"
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json"
    }

    try:
        response = requests.post(url, headers=headers, timeout=30)
    except requests.RequestException as e:
        assert False, f"Request failed with exception: {e}"

    assert response.status_code in (200, 204), f"Expected status code 200 or 204 but got {response.status_code}"

    if response.status_code == 200:
        try:
            json_resp = response.json()
        except ValueError:
            json_resp = None

        if json_resp:
            assert ("message" in json_resp or "detail" in json_resp), "Response JSON missing confirmation field"

test_post_api_auth_sign_out_with_valid_bearer_token()